<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ArrowLeft, Mail, MapPin, Pencil, Phone, ShieldCheck, UserRound, Archive } from 'lucide-vue-next';
import MemberEntryModal from './MemberEntryModal.vue';
import { api, errorMessage } from '../../services/api'; import { useAuthStore } from '../../stores/auth'; import { date } from '../../utils/format'; import type { Member } from './types';
import MemberAvatar from '../../components/ui/MemberAvatar.vue'; import StatusBadge from '../../components/ui/StatusBadge.vue'; import AppButton from '../../components/ui/AppButton.vue'; import LoadingState from '../../components/ui/LoadingState.vue'; import AppModal from '../../components/modals/AppModal.vue'; import ConfirmDialog from '../../components/modals/ConfirmDialog.vue'; import AppForm from '../../components/forms/AppForm.vue'; import AppInput from '../../components/ui/AppInput.vue'; import FileUploader from '../../components/forms/FileUploader.vue';
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const own = computed(() => route.path === '/my-profile'); const member = ref<Member>(); const busy = ref(false); const loading = ref(false); const error = ref(''); const actionError = ref(''); const archiveOpen = ref(false); const loginOpen = ref(false); const email = ref(''); const password = ref(''); const success = ref('');
const editorOpen = computed(() => route.query.entry === 'edit' && auth.can('members.write'));
async function closeEditor() { const { entry, ...query } = route.query; await router.replace({ query }); }
async function saved(_member: Member, photoError?: string) { success.value = 'Member profile updated successfully.'; await closeEditor(); await load(); if (photoError) error.value = `Profile saved, but photo change failed: ${photoError}. Retry below.`; }
async function load() { loading.value = true; error.value = ''; try { member.value = (await api.get<Member>(own.value ? '/members/me' : `/members/${route.params.id}`)).data; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function archive() { if (!member.value) return; busy.value = true; actionError.value = ''; try { await api.delete(`/members/${member.value.id}`, { data: { version: member.value.version } }); await router.push('/members'); } catch (e) { actionError.value = errorMessage(e); } finally { busy.value = false; } }
async function createLogin() { if (!member.value) return; busy.value = true; actionError.value = ''; try { await api.post(`/members/${member.value.id}/login`, { email: email.value, password: password.value }); loginOpen.value = false; password.value = ''; success.value = 'Member login created. Share the temporary password privately with the member.'; await load(); } catch (e) { actionError.value = errorMessage(e); } finally { busy.value = false; } }
async function uploadPhoto(file: File) { if (!member.value) return; busy.value = true; error.value = ''; try { const body = new FormData(); body.append('photo', file); await api.post(`/members/${member.value.id}/photo`, body); await load(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function removePhoto() {
  const documentId = member.value?.documents[0]?.id;
  if (!member.value || !documentId) return;
  busy.value = true; error.value = ''; success.value = '';
  try { await api.delete(`/members/${member.value.id}/photo`, { data: { documentId } }); await load(); success.value = 'Member photo removed successfully.'; }
  catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
onMounted(load);
</script>
<template><RouterLink v-if="!own" to="/members" class="back-link"><ArrowLeft :size="16" /> Back to members</RouterLink><div class="page-heading"><div><span class="eyebrow">{{ own ? 'YOUR PERSONAL SPACE' : 'MEMBER MANAGEMENT' }}</span><h1>{{ own ? 'My dashboard' : 'Member profile' }}<span class="heading-dot">.</span></h1><p>{{ own ? 'Your membership details, always close at hand.' : 'The person behind the membership.' }}</p></div><div v-if="member && auth.can('members.write') && !own" class="button-row"><AppButton v-if="auth.can('members.archive')" variant="secondary" @click="archiveOpen = true; actionError = ''"><Archive :size="16" /> Archive</AppButton><AppButton @click="router.push({ query: { ...route.query, entry: 'edit' } })"><Pencil :size="18" /> Edit profile</AppButton></div></div><div v-if="error" class="alert error" role="alert">{{ error }} <AppButton variant="ghost" @click="load">Reload</AppButton></div><div v-if="route.query.photoError" class="alert error" role="alert">Profile saved. Photo change failed: {{ route.query.photoError }}. Retry below.</div><div v-if="success" class="alert success" role="status">{{ success }}</div><LoadingState v-if="loading" /><template v-else-if="member"><section class="panel profile-hero"><MemberAvatar :name="member.fullName" :document-id="member.documents[0]?.id" large /><div><span class="member-number">{{ member.memberNo }}</span><h2>{{ member.fullName }}</h2><p>Member since {{ date(member.joinedAt) }}</p></div><StatusBadge :status="member.status" /></section><div class="profile-grid"><section class="panel profile-info"><div class="panel-heading"><h2>Contact information</h2><UserRound :size="19" /></div><dl class="detail-list"><div><dt><Phone :size="16" />Phone number</dt><dd>{{ member.phone }}</dd></div><div><dt><Mail :size="16" />Email address</dt><dd>{{ member.email || 'Not provided' }}</dd></div><div><dt><MapPin :size="16" />Address</dt><dd class="preserve-lines">{{ member.address }}</dd></div></dl><fieldset v-if="auth.can('members.write') && !own" :disabled="busy"><FileUploader :document-id="member.documents[0]?.id" :name="member.fullName" @selected="uploadPhoto" @remove="removePhoto" /></fieldset></section><section class="panel profile-info"><div class="panel-heading"><h2>Nominees</h2><span class="count-pill">{{ member.nominees.length }}</span></div><article v-for="(nominee, i) in member.nominees" :key="i" class="nominee-card"><div class="nominee-card-heading"><strong>{{ nominee.fullName }}</strong><span class="share-badge">{{ nominee.sharePercent }}%</span></div><span class="muted">{{ nominee.relationship }}</span><p>{{ nominee.phone }}</p><p class="muted preserve-lines">{{ nominee.address }}</p></article></section></div><section v-if="!own" class="panel portal-panel"><ShieldCheck :size="26" /><div><h2>Member portal access</h2><p>{{ member.user ? `Login account: ${member.user.email}` : 'Give this member a private, view-only account to see their own profile.' }}</p></div><AppButton v-if="!member.user && auth.can('users.manage')" variant="secondary" @click="loginOpen = true; email = member.email ?? ''; actionError = ''">Create member login</AppButton><StatusBadge v-else-if="member.user" :status="member.user.isActive ? 'ACTIVE' : 'INACTIVE'" /></section><section v-else class="panel member-financial-note"><ShieldCheck :size="26" /><div><h2>Your personal, view-only dashboard</h2><p>Contact your administrator to update your profile. Deposits, withdrawals, loans and investment statements will become available when the financial modules are introduced.</p></div></section></template><MemberEntryModal :open="editorOpen && !!member" :member-id="member?.id" @close="closeEditor" @saved="saved" /><ConfirmDialog :open="archiveOpen" title="Archive this member?" message="This removes the member from the active directory and disables their login. Their records and audit history are retained." :busy="busy" :error="actionError" @close="archiveOpen = false" @confirm="archive" /><AppModal :open="loginOpen" title="Create member login" :busy="busy" @close="loginOpen = false"><p class="muted">The member can only view their own profile. They must change this temporary password on first sign-in.</p><AppForm :error="actionError" :busy="busy" @submit="createLogin"><AppInput v-model="email" label="Login email" type="email" required maxlength="191" autocomplete="off" /><AppInput v-model="password" label="Temporary password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /><small class="muted">12–128 characters with uppercase, lowercase and a number.</small><AppButton type="submit" :loading="busy">Create login</AppButton></AppForm></AppModal></template>
